package add_route

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "add_route"
	command.Identifiers = []string{"add-route"}
	command.Category = "Server System"
	command.Help = "Declare a new http route"
	command.LongDescription = "Writes sandbox/internal/routes/<name>/route.yaml and a stub handler.go, then runs build so the route's new.go — the api.Route that lands in sandbox.Routes — is generated. The trigger is normalized to start with /, and defaults to /<name>."
	command.Examples = []string{"add-route create-user --trigger /users --method POST --help \"Create a user\" --category Users"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "trigger",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the first literal segment of the path, always starting with / (defaults to /<name>)",
			Examples:    []string{"--trigger /users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger"},
		},
		{
			Id:          "method",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the http method the route answers: GET, POST, PUT, PATCH, DELETE, HEAD or OPTIONS",
			Examples:    []string{"--method POST"},
			Default:     "GET",
			HasDefault:  true,
			Identifiers: []string{"--method", "-m"},
		},
		{
			Id:          "help",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "one-line description of the route",
			Examples:    []string{"--help \"Create a user\""},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--help"},
		},
		{
			Id:          "category",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the heading the route is listed under in docs/Routes",
			Examples:    []string{"--category Users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--category"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"add-route --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route name (becomes the directory sandbox/internal/routes/<name> and its Go package)",
			Examples:    []string{"add-route create-user"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
